create table if not exists catalog_lists (table_name text, column_name text, value text, sort int, primary key (table_name, column_name, value));
delete from catalog_lists;
alter table catalog_lists enable row level security;
drop policy if exists catalog_lists_admin_all on catalog_lists;
create policy catalog_lists_admin_all on catalog_lists for all to authenticated using (is_admin()) with check (is_admin());
insert into catalog_lists values ('cards','instrument_type','Credit Card',0) on conflict do nothing;
insert into catalog_lists values ('cards','instrument_type','Debit Card',1) on conflict do nothing;
insert into catalog_lists values ('cards','instrument_type','Charge Card',2) on conflict do nothing;
insert into catalog_lists values ('cards','instrument_type','Prepaid Card',3) on conflict do nothing;
update cards set instrument_type = 'Credit Card' where instrument_type <> 'Credit Card' and lower(trim(instrument_type)) = lower('Credit Card');
update cards set instrument_type = 'Debit Card' where instrument_type <> 'Debit Card' and lower(trim(instrument_type)) = lower('Debit Card');
update cards set instrument_type = 'Charge Card' where instrument_type <> 'Charge Card' and lower(trim(instrument_type)) = lower('Charge Card');
update cards set instrument_type = 'Prepaid Card' where instrument_type <> 'Prepaid Card' and lower(trim(instrument_type)) = lower('Prepaid Card');
do $$ begin
  if not exists (select 1 from cards where instrument_type is not null and lower(instrument_type) not in ('n/a','na') and instrument_type <> all(array['Credit Card','Debit Card','Charge Card','Prepaid Card'])) then
    alter table cards drop constraint if exists chk_cards_instrument_type;
    alter table cards add constraint chk_cards_instrument_type check (instrument_type is null or lower(instrument_type) in ('n/a','na') or instrument_type = any(array['Credit Card','Debit Card','Charge Card','Prepaid Card']));
  else raise notice 'list not enforced (existing values differ): cards.instrument_type';
  end if;
end $$;
