update offers set category = 'Shopping' where category <> 'Shopping' and lower(trim(category)) = lower('Shopping');
update offers set category = 'Travel' where category <> 'Travel' and lower(trim(category)) = lower('Travel');
update offers set category = 'Dining' where category <> 'Dining' and lower(trim(category)) = lower('Dining');
update offers set category = 'Entertainment' where category <> 'Entertainment' and lower(trim(category)) = lower('Entertainment');
