update offers set category = 'Utilities' where category <> 'Utilities' and lower(trim(category)) = lower('Utilities');
update offers set category = 'All' where category <> 'All' and lower(trim(category)) = lower('All');
do $$ begin
  if not exists (select 1 from offers where category is not null and lower(category) not in ('n/a','na') and category <> all(array['Shopping','Travel','Dining','Entertainment','Fuel','Grocery','Utilities','All'])) then
    alter table offers drop constraint if exists chk_offers_category;
